1	package com.example.starter.evidence;
2	
3	import com.example.starter.error.ApiException;
4	import com.example.starter.evidence.dto.CommandRequest;
5	import com.example.starter.evidence.dto.CustodyChainView;
6	import com.example.starter.evidence.dto.EvidenceView;
7	import com.example.starter.evidence.dto.InspectionView;
8	import com.example.starter.evidence.dto.IntakeRequest;
9	import com.example.starter.evidence.dto.SealInspectionRequest;
10	import com.example.starter.evidence.dto.TransferInitiateRequest;
11	import com.example.starter.evidence.dto.TransferView;
12	import com.fasterxml.jackson.databind.ObjectMapper;
13	import org.springframework.stereotype.Service;
14	import org.springframework.transaction.annotation.Transactional;
15	
16	import java.time.LocalDateTime;
17	import java.util.List;
18	import java.util.Optional;
19	
20	/**
21	 * 证物封存交接核心服务。所有写操作在单事务内完成：
22	 * 先锁定证物行（SELECT ... FOR UPDATE），再校验状态机并落库，最后写入幂等日志。
23	 * 交接记录与核验记录只追加；证物业务字段入库后不可修改。
24	 */
25	@Service
26	public class EvidenceService {
27	
28	    static final String OP_INTAKE = "INTAKE";
29	    static final String OP_TRANSFER_INITIATE = "TRANSFER_INITIATE";
30	    static final String OP_TRANSFER_ACCEPT = "TRANSFER_ACCEPT";
31	    static final String OP_TRANSFER_CANCEL = "TRANSFER_CANCEL";
32	    static final String OP_SEAL_INSPECTION = "SEAL_INSPECTION";
33	
34	    private final EvidenceRepository evidenceRepository;
35	    private final TransferRecordRepository transferRepository;
36	    private final SealInspectionRepository inspectionRepository;
37	    private final CommandLogRepository commandLogRepository;
38	    private final ObjectMapper objectMapper;
39	
40	    public EvidenceService(EvidenceRepository evidenceRepository,
41	                           TransferRecordRepository transferRepository,
42	                           SealInspectionRepository inspectionRepository,
43	                           CommandLogRepository commandLogRepository,
44	                           ObjectMapper objectMapper) {
45	        this.evidenceRepository = evidenceRepository;
46	        this.transferRepository = transferRepository;
47	        this.inspectionRepository = inspectionRepository;
48	        this.commandLogRepository = commandLogRepository;
49	        this.objectMapper = objectMapper;
50	    }
51	
52	    /**
53	     * 证物入库：初始状态 SEALED，保管人为操作人。evidenceKey 全局唯一。
54	     */
55	    @Transactional
56	    public StoredResponse intake(String actorId, IntakeRequest request, String requestHash) {
57	        Optional<StoredResponse> replay = checkReplay(request.commandKey(), requestHash);
58	        if (replay.isPresent()) {
59	            return replay.get();
60	        }
61	        if (evidenceRepository.findByKey(request.evidenceKey()).isPresent()) {
62	            throw ApiException.conflict("证物已存在: " + request.evidenceKey());
63	        }
64	        LocalDateTime now = LocalDateTime.now();
65	        evidenceRepository.insert(request.evidenceKey(), request.caseKey(), request.category(),
66	                request.sealNo(), actorId, now);
67	        Evidence evidence = evidenceRepository.findByKey(request.evidenceKey()).orElseThrow();
68	        return record(request.commandKey(), OP_INTAKE, actorId, requestHash, 201, toView(evidence));
69	    }
70	
71	    /**
72	     * 发起交接：仅当前保管人，证物须为 SEALED，接收人须与发起人不同；成功后进入 TRANSFER_PENDING。
73	     */
74	    @Transactional
75	    public StoredResponse initiateTransfer(String actorId, String evidenceKey,
76	                                           TransferInitiateRequest request, String requestHash) {
77	        Optional<StoredResponse> replay = checkReplay(request.commandKey(), requestHash);
78	        if (replay.isPresent()) {
79	            return replay.get();
80	        }
81	        Evidence evidence = lockEvidence(evidenceKey);
82	        if (request.toCustodian().equals(actorId)) {
83	            throw ApiException.badRequest("接收人不能与发起保管人相同");
84	        }
85	        requireSealIntact(evidence);
86	        requireCustodian(evidence, actorId);
87	        if (evidence.status() == EvidenceStatus.TRANSFER_PENDING) {
88	            throw ApiException.conflict("证物已存在待接收交接: " + evidenceKey);
89	        }
90	        LocalDateTime now = LocalDateTime.now();
91	        transferRepository.insert(evidenceKey, actorId, request.toCustodian(), now);
92	        evidenceRepository.updateStatus(evidenceKey, EvidenceStatus.TRANSFER_PENDING, now);
93	        TransferRecord pending = transferRepository.findPendingByEvidenceKey(evidenceKey).orElseThrow();
94	        return record(request.commandKey(), OP_TRANSFER_INITIATE, actorId, requestHash,
95	                200, toView(pending));
96	    }
97	
98	    /**
99	     * 接受交接：仅指定接收人；保管人原子切换为接收人并回到 SEALED。
100	     */
101	    @Transactional
102	    public StoredResponse acceptTransfer(String actorId, String evidenceKey,
103	                                         CommandRequest request, String requestHash) {
104	        Optional<StoredResponse> replay = checkReplay(request.commandKey(), requestHash);
105	        if (replay.isPresent()) {
106	            return replay.get();
107	        }
108	        Evidence evidence = lockEvidence(evidenceKey);
109	        requireSealIntact(evidence);
110	        TransferRecord pending = requirePending(evidence, evidenceKey);
111	        if (!pending.toCustodian().equals(actorId)) {
112	            throw ApiException.conflict("操作人不是指定接收人: " + actorId);
113	        }
114	        LocalDateTime now = LocalDateTime.now();
115	        if (!transferRepository.decide(pending.id(), TransferStatus.ACCEPTED, now)) {
116	            throw ApiException.conflict("交接已被处理: " + evidenceKey);
117	        }
118	        evidenceRepository.updateCustody(evidenceKey, actorId, EvidenceStatus.SEALED, now);
119	        Evidence updated = evidenceRepository.findByKey(evidenceKey).orElseThrow();
120	        return record(request.commandKey(), OP_TRANSFER_ACCEPT, actorId, requestHash,
121	                200, toView(updated));
122	    }
123	
124	    /**
125	     * 取消交接：仅原保管人（发起人）可取消，接收人不能自行取消；证物回到 SEALED。
126	     */
127	    @Transactional
128	    public StoredResponse cancelTransfer(String actorId, String evidenceKey,
129	                                         CommandRequest request, String requestHash) {
130	        Optional<StoredResponse> replay = checkReplay(request.commandKey(), requestHash);
131	        if (replay.isPresent()) {
132	            return replay.get();
133	        }
134	        Evidence evidence = lockEvidence(evidenceKey);
135	        requireSealIntact(evidence);
136	        TransferRecord pending = requirePending(evidence, evidenceKey);
137	        if (!pending.fromCustodian().equals(actorId)) {
138	            throw ApiException.conflict("仅原保管人可取消交接: " + actorId);
139	        }
140	        LocalDateTime now = LocalDateTime.now();
141	        if (!transferRepository.decide(pending.id(), TransferStatus.CANCELLED, now)) {
142	            throw ApiException.conflict("交接已被处理: " + evidenceKey);
143	        }
144	        evidenceRepository.updateStatus(evidenceKey, EvidenceStatus.SEALED, now);
145	        Evidence updated = evidenceRepository.findByKey(evidenceKey).orElseThrow();
146	        return record(request.commandKey(), OP_TRANSFER_CANCEL, actorId, requestHash,
147	                200, toView(updated));
148	    }
149	
150	    /**
151	     * 封条核验：仅当前保管人，待接收期间禁止核验。
152	     * 通过仅追加不可变记录；失败使证物进入 SEAL_BROKEN（终态）。
153	     */
154	    @Transactional
155	    public StoredResponse inspectSeal(String actorId, String evidenceKey,
156	                                      SealInspectionRequest request, String requestHash) {
157	        Optional<StoredResponse> replay = checkReplay(request.commandKey(), requestHash);
158	        if (replay.isPresent()) {
159	            return replay.get();
160	        }
161	        Evidence evidence = lockEvidence(evidenceKey);
162	        requireCustodian(evidence, actorId);
163	        if (evidence.status() == EvidenceStatus.TRANSFER_PENDING) {
164	            throw ApiException.conflict("待接收期间禁止封条核验: " + evidenceKey);
165	        }
166	        LocalDateTime now = LocalDateTime.now();
167	        inspectionRepository.insert(evidenceKey, actorId, request.passed(), request.note(), now);
168	        if (!request.passed() && evidence.status() != EvidenceStatus.SEAL_BROKEN) {
169	            evidenceRepository.updateStatus(evidenceKey, EvidenceStatus.SEAL_BROKEN, now);
170	        }
171	        List<SealInspection> inspections = inspectionRepository.findByEvidenceKey(evidenceKey);
172	        SealInspection created = inspections.get(inspections.size() - 1);
173	        return record(request.commandKey(), OP_SEAL_INSPECTION, actorId, requestHash,
174	                200, toView(created));
175	    }
176	
177	    /**
178	     * 查询当前操作人可交接的证物（本人保管且 SEALED）。
179	     */
180	    @Transactional(readOnly = true)
181	    public List<EvidenceView> listTransferable(String actorId) {
182	        return evidenceRepository.findTransferable(actorId).stream().map(this::toView).toList();
183	    }
184	
185	    /**
186	     * 查询完整保管链：证物当前状态 + 全部交接记录 + 全部核验记录。
187	     */
188	    @Transactional(readOnly = true)
189	    public CustodyChainView custodyChain(String evidenceKey) {
190	        Evidence evidence = evidenceRepository.findByKey(evidenceKey)
191	                .orElseThrow(() -> ApiException.notFound("证物不存在: " + evidenceKey));
192	        List<TransferView> transfers = transferRepository.findByEvidenceKey(evidenceKey)
193	                .stream().map(this::toView).toList();
194	        List<InspectionView> inspections = inspectionRepository.findByEvidenceKey(evidenceKey)
195	                .stream().map(this::toView).toList();
196	        return new CustodyChainView(toView(evidence), transfers, inspections);
197	    }
198	
199	    private Evidence lockEvidence(String evidenceKey) {
