2	
3	import com.example.starter.error.ApiException;
4	import com.fasterxml.jackson.databind.ObjectMapper;
5	import org.springframework.dao.DuplicateKeyException;
6	import org.springframework.stereotype.Component;
7	
8	import java.nio.charset.StandardCharsets;
9	import java.security.MessageDigest;
10	import java.security.NoSuchAlgorithmException;
11	import java.util.HexFormat;
12	import java.util.Optional;
13	import java.util.function.Supplier;
14	
15	/**
16	 * 幂等编排（非事务）：计算请求指纹、处理并发下 command_key 唯一约束冲突。
17	 * 同键同参重放返回首次结果；同键改参返回 409；并发重复插入时回滚后重放先提交事务的结果。
18	 */
19	@Component
20	public class IdempotencyAdvisor {
21	
22	    private final CommandLogRepository commandLogRepository;
23	    private final ObjectMapper objectMapper;
24	
25	    public IdempotencyAdvisor(CommandLogRepository commandLogRepository, ObjectMapper objectMapper) {
26	        this.commandLogRepository = commandLogRepository;
27	        this.objectMapper = objectMapper;
28	    }
29	
30	    /**
31	     * 计算请求指纹：操作类型 + 操作人 + 证物键 + 请求体规范化 JSON 的 SHA-256。
32	     */
33	    public String hash(String operation, String actorId, String evidenceKey, Object request) {
34	        try {
35	            String canonical = String.join("\n",
36	                    operation,
37	                    actorId == null ? "" : actorId,
38	                    evidenceKey == null ? "" : evidenceKey,
39	                    objectMapper.writeValueAsString(request));
40	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
41	            return HexFormat.of().formatHex(digest.digest(canonical.getBytes(StandardCharsets.UTF_8)));
42	        } catch (NoSuchAlgorithmException e) {
43	            throw new IllegalStateException("SHA-256 不可用", e);
44	        } catch (Exception e) {
45	            throw new IllegalStateException("请求序列化失败", e);
46	        }
47	    }
