package com.example.starter.evidence.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;
import java.util.List;

/**
 * 批量入库请求。保管人随请求体提交；items 与 measuredWeights 按下标一一对应。
 * 清单内 evidenceKey 重复或已存在整批 400；单件数据格式非法（重量非正、描述为空等）整批 422。
 *
 * @param intakeKey      批次幂等键，全局唯一；同键同参（清单换序视为同参）重放首次结果
 * @param custodianId    保管人，入库后成为全部证物的当前保管人
 * @param items          证物清单，1～50 件
 * @param measuredWeights 实测重量列表（单位千克），与 items 等长并按下标一一对应
 */
public record BatchIntakeRequest(
        @NotBlank @Size(max = 64) String intakeKey,
        @NotBlank @Size(max = 64) String custodianId,
        @NotNull @Size(min = 1, max = 50) List<BatchIntakeItem> items,
        @NotNull @Size(min = 1, max = 50) List<BigDecimal> measuredWeights) {

    /**
     * 批量入库清单单项。字段级格式（非空、重量为正且两位小数）由服务层逐项校验并汇总为 422。
     *
     * @param evidenceKey    证物业务键，全局唯一
     * @param description    证物描述，非空
     * @param declaredWeight 申报重量（单位千克，大于0的两位小数）
     */
    public record BatchIntakeItem(
            @Size(max = 64) String evidenceKey,
            @Size(max = 512) String description,
            BigDecimal declaredWeight) {
    }
}

package com.example.starter.evidence.dto;

import com.example.starter.evidence.EvidenceStatus;
import com.example.starter.evidence.ReviewStatus;
import com.example.starter.evidence.WeightStatus;

import java.math.BigDecimal;
import java.util.List;

/**
 * 批量入库响应：逐件创建结果 + 整体差异统计。
 *
 * @param intakeKey       批次幂等键
 * @param custodianId     保管人
 * @param totalCount      本批证物总数
 * @param matchedCount    重量一致（MATCHED）件数
 * @param discrepantCount 差异超5%（DISCREPANT）件数
 * @param items           逐件创建结果，顺序与请求清单一致
 */
public record BatchIntakeResponse(
        String intakeKey,
        String custodianId,
        int totalCount,
        int matchedCount,
        int discrepantCount,
        List<Item> items) {

    /**
     * 逐件创建结果。
     *
     * @param evidenceKey    证物业务键
     * @param status         证物状态，批量入库后恒为 SEALED
     * @param declaredWeight 申报重量（单位千克）
     * @param measuredWeight 实测重量（单位千克）
     * @param weightStatus   重量核对结果：MATCHED / DISCREPANT
     * @param reviewStatus   复核状态：DISCREPANT 为 PENDING，其余为 NONE
     */
    public record Item(
            String evidenceKey,
            EvidenceStatus status,
            BigDecimal declaredWeight,
            BigDecimal measuredWeight,
            WeightStatus weightStatus,
            ReviewStatus reviewStatus) {
    }
}

